def solve(ranges):
    out = []
    for r in ranges:
        start, end = r[0], r[1]
        if out and start <= out[-1][1]:
            if end > out[-1][1]:
                out[-1][1] = end
        else:
            out.append([start, end])
    return out

def solve(ranges):
    ordered = sorted([list(r) for r in ranges])
    out = []
    for start, end in ordered:
        if out and start < out[-1][1]:
            if end > out[-1][1]:
                out[-1][1] = end
        else:
            out.append([start, end])
    return out

def solve(xs):
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    if not counts:
        return 0
    return max(counts.values())

def solve(xs):
    best = 1
    run = 1
    for i in range(1, len(xs)):
        if xs[i] == xs[i - 1]:
            run += 1
            if run > best:
                best = run
        else:
            run = 1
    return best

def solve(n):
    table = [(1000, "M"), (500, "D"), (100, "C"), (90, "XC"), (50, "L"),
             (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    out = []
    left = n
    for value, sign in table:
        while left >= value:
            out.append(sign)
            left -= value
    return "".join(out)

